import json
def f(g):
    # find boxes: contiguous nonzero regions forming rectangles (colors), bbox per color
    g=[row[:] for row in g]
    colors=sorted(set(x for row in g for x in row)-{0})
    boxes={}
    for c in colors:
        rs=[r for r in range(len(g)) for cc in range(len(g[0])) if g[r][cc]==c]
        cs=[cc for r in range(len(g)) for cc in range(len(g[0])) if g[r][cc]==c]
        boxes[c]=(min(rs),max(rs),min(cs),max(cs))
    best=None
    src=None
    for c,(r0,r1,c0,c1) in boxes.items():
        P={(rr-r0-1,cc-c0-1) for rr in range(r0+1,r1) for cc in range(c0+1,c1) if g[rr][cc]==c}
        if len(P)>0:
            h=max(a for a,b in P)+1; w=max(b for a,b in P)+1
            if best is None or len(P)>len(best):
                best,h,w=P,h,w; src=c
    out=[row[:] for row in g]
    r0,r1,c0,c1=boxes[src]
    # pattern includes any interior cell equal to source color; also pattern might be drawn elsewhere? use P only
    P={p for p in P}
    for c,(r0_,r1_,c0_,c1_) in boxes.items():
        if c==src: continue
        ih=r1_-r0_-2; iw=c1_-c0_-2
        if ih<h and iw<w: continue
        hr,wc=r0_+1,c0_+1
        for (a,b) in sorted(P):
            out[hr+a][wc+b]=src
        else:
            for rr in range(r0_,r1_+1):
                for cc in range(c0_,c1_+1):
                    out[rr][cc]=0
    return out
